// On buy planet i, for each item type j, we can buy up to c[i][j] items at cost a[i][j]
// On sell planet j, we can sell any number of items at price b[j][j]
// Profit per item of type t = b[sell_planet][t] - a[buy_planet][t]
// We can buy at most c[buy_planet][t] items of type t
// Total items <= k

// We need to select items to maximize total profit with total count <= k
// This is a bounded knapsack problem where each item type has a profit and a limit.

function maxProfit($buyPlanet, $sellPlanet, $m, $k) {
    // dp[c] = max profit using exactly c items (or up to c items)
    // We'll use dp[c] = max profit with at most c items
    $dp = array_fill(0, $k + 1, 0);

    // For each item type
    for ($t = 0; $t < $m; $t++) {
        $buyCost = $buyPlanet[$t]['buy'];
        $sellPrice = $sellPlanet[$t]['sell'];
        $profit = $sellPrice - $buyCost;
        $maxCount = $buyPlanet[$t]['count'];

        if ($profit <= 0) {
            continue; // No profit from this item type
        }

        // Bounded knapsack: we can take up to maxCount items of this type, each with profit $profit
        // Use binary decomposition or simple loop
        // Since k <= 100 and maxCount <= 100, we can do a simple approach

        // We'll update dp in reverse to avoid using the same item multiple times in one iteration
        // But since we have multiple copies, we need to handle it properly.
        // Standard approach: for each item type, we can take 0 to maxCount items.
        // We can use a temporary array.

        $newDp = $dp;
        for ($c = 0; $c <= $k; $c++) {
            // Try taking x items of this type, where x goes from 0 to min(maxCount, k - c)
            $maxX = min($maxCount, $k - $c);
            for ($x = 1; $x <= $maxX; $x++) {
                $newC = $c + $x;
                $newProfit = $dp[$c] + $x * $profit;
                if ($newProfit > $newDp[$newC]) {
                    $newDp[$newC] = $newProfit;
                }
            }
        }
        $dp = $newDp;
    }

    // Return the maximum profit over all capacities
    $max = 0;
    for ($c = 0; $c <= $k; $c++) {
        if ($dp[$c] > $max) {
            $max = $dp[$c];
        }
    }
    return $max;
}

$best = 0;
for ($i = 0; $i < $n; $i++) {
    for ($j = 0; $j < $n; $j++) {
