        // - Each item type j has a "profit" of (sellPrice[j] - buyPrice[j]) per item
        // - We can take at most count[j] items of type j
        // - Total items taken <= k

        // Since m and k are up to 100, we can use DP
        // dp[i][w] = max profit using first i item types with total weight w
        // But we can optimize to 1D DP

        $dp = array_fill(0, $k + 1, 0);

        for ($j = 0; $j < $m; $j++) {
            $buyPrice = $planets[$buyPlanet]['items'][$j]['buy'];
            $sellPrice = $planets[$sellPlanet]['items'][$j]['sell'];
