            if ($profitPerItem <= 0) continue;

            // Bounded knapsack: we can take 0 to maxCount items of type j
            // Use the standard technique: process from high to low to avoid using same item multiple times in one iteration
            // But since we have multiple copies, we need to handle it properly

            // For each possible number of items of this type (from maxCount down to 1)
            // Actually, we can use the binary decomposition or just iterate carefully

