            // Let's use the standard bounded knapsack approach with binary decomposition
            $remaining = $maxCount;
            $power = 1;
            while ($remaining > 0) {
                $take = min($power, $remaining);
                $weight = $take;
                $value = $take * $profitPerItem;

                // 0/1 knapsack update for this "group"
                for ($w = $k; $w >= $weight; $w--) {
                    $dp[$w] = max($dp[$w], $dp[$w - $weight] + $value);
                }

                $remaining -= $take;
                $power *= 2;
            }
